"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def SearchFiles(directory, target_extension):
    matching_files = []
    for item in directory.getItems():
        if item.isFolder():
            matching_files.extend(SearchFiles(item, target_extension))
        elif (item.getExtension() == target_extension):
            matching_files.append(item.path)
    return matching_files
class File:
    def __init__(self, path):
        self.path = path

    def isFolder(self):
        return False

    def getExtension(self):
        return self.path.split('.')[-1]


class Folder:
    def __init__(self, name, items):
        self.name = name
        self.items = items

    def isFolder(self):
        return True

    def getItems(self):
        return self.items


# ---- Build a mock directory tree ----

root = Folder("root", [
    File("a.txt"),
    File("b.jpg"),
    Folder("sub1", [
        File("c.txt"),
        File("d.png")
    ]),
    Folder("sub2", [
        Folder("deep", [
            File("e.txt"),
            File("f.doc")
        ])
    ])
])


# ---- Run your search ----

result = SearchFiles(root, "txt")
print(result)
